import{Lt as e,Vt as t,_t as n,bt as r,mt as i,vt as a,yt as o}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";import{n as s,t as c}from"./chunks/PluginFeedback.BpCHXCV1.js";var l=JSON.parse(`{"title":"阿里翻译接口申请及配置","description":"","frontmatter":{"plugin":"windingwind/zotero-pdf-translate"},"headers":[],"relativePath":"user-guide/plugins/translate/aliyun.md","filePath":"wiki/user-guide/plugins/translate/aliyun.md"}`),u=Object.assign({name:`user-guide/plugins/translate/aliyun.md`},{setup(l){return(l,u)=>{let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),n(`div`,null,[u[0]||=i(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidepluginstranslatealiyun.md for this page in Markdown format`,-1),u[1]||=i(`h1`,{id:`阿里翻译接口申请及配置`,tabindex:`-1`},[o(`阿里翻译接口申请及配置 `),i(`a`,{class:`header-anchor`,href:`#阿里翻译接口申请及配置`,"aria-label":`Permalink to “阿里翻译接口申请及配置”`},`​`)],-1),r(s),u[2]||=a(`<h2 id="_1-翻译接口申请" tabindex="-1">1. 翻译接口申请 <a class="header-anchor" href="#_1-翻译接口申请" aria-label="Permalink to “1. 翻译接口申请”">​</a></h2><p>打开 <a href="https://www.aliyun.com/product/ai/alimt?spm=5176.19720258.J_8058803260.278.e9392c4a5eczxp" target="_blank" rel="noreferrer">阿里翻译</a> 页面，点击立即开通，在登录页面，使用支付宝扫码登录。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">提示</p><p>注意，如果第一次开通，可能会提示你需要进行实名认证，按照提示进行认证即可。</p></div><p><img src="/assets/aliyun-1.CMqIkEW3.png" alt="开通页面" width="1080" height="409"></p><p>使用支付宝扫码登录：</p><p><img src="/assets/aliyun-2.bhixLFUD.png" alt="扫码页面" width="901" height="563"></p><p>扫码成功后，跳转到控制台（如果未跳转到控制台，请访问），分别有两个接口，按照需求进行开通：</p><ol><li>通用版，支持全球 214 种语言互译，采用最先进的神经网络翻译模型，适用于日常沟通、出国旅行等应用场景。</li><li>专业版，电商、社交、医疗 3 大领域积累千万级双语语料和百万专业领域双语术语，推出多个专业领域翻译引擎。</li></ol><p><img src="/assets/aliyun-3.GS-4dR_9.png" alt="通用版与专业版" width="1080" height="540"></p><p>下面以专业版为例，直接点击立即开通：</p><p><img src="/assets/aliyun-4.BJdcnYoL.png" alt="申请开通" width="1080" height="525"></p><p><img src="/assets/aliyun-5.DEPUYawI.png" alt="开通完成" width="1080" height="681"></p><p>你可以在 <a href="https://mt.console.aliyun.com/service" target="_blank" rel="noreferrer">控制台 - 服务开通与管理</a> 里查看已开通的服务：</p><p><img src="/assets/aliyun-6.ClqwZHOZ.png" alt="查看服务" width="1080" height="441"></p><p>把鼠标移动到右上角，点击下面的 AccessKey 管理：</p><p><img src="/assets/aliyun-7.BTzs7H6C.png" alt="获取密钥" width="702" height="439"></p><p>点击继续使用 AccessKey：</p><p><img src="/assets/aliyun-8.D6I-oBnD.png" alt="子账户开通提示，可以不必开通" width="1080" height="373"></p><p>如果后面忘记了 AccessKey 或发生泄露，可以重新在这申请一个新的：</p><p><img src="/assets/aliyun-9.DsGaIi0f.png" alt="下载密钥" width="951" height="368"></p><h2 id="_2-zotero-翻译引擎设置" tabindex="-1">2. Zotero 翻译引擎设置 <a class="header-anchor" href="#_2-zotero-翻译引擎设置" aria-label="Permalink to “2. Zotero 翻译引擎设置”">​</a></h2><p>打开「Zotero 设置」，转到「翻译」选项卡，在「翻译服务」里选择「阿里」，按照 <code>AccessKey ID#AccessKey Secret</code> 格式，输入到「密钥」中。注意这里的 <code>AccessKey ID</code> 和 <code>AccessKey Secret</code> 从你上面下载的 csv 文件里查看。</p><p><img src="/assets/aliyun-10.CvsN5G3M.png" alt="翻译插件设置窗口" width="802" height="632"></p><p>打开一篇英文 PDF，使用阿里的引擎，试试划词翻译正常不。有中文输出说明配置正常。</p><p><img src="/assets/aliyun-11.DWlxQXzW.png" alt="测试配置是否成功" width="1080" height="470"></p><h2 id="_3-翻译使用量查看" tabindex="-1">3. 翻译使用量查看 <a class="header-anchor" href="#_3-翻译使用量查看" aria-label="Permalink to “3. 翻译使用量查看”">​</a></h2><p>阿里云的翻译流量会每月更新，请不要超过每月的使用额度，不然会自动产生扣费。免费额度快用光了，请切换到其他引擎，查看具体的使用量，到 <a href="https://mt.console.aliyun.com/monitor" target="_blank" rel="noreferrer">控制台 - 监控统计</a> 查看。</p><p><img src="/assets/aliyun-12.qLRzJrhA.png" alt="翻译使用量查看" width="1080" height="540"></p>`,28),r(c),r(d),r(f)])}}});export{l as __pageData,u as default};